examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    MonarchText(text = {{title}}, style = MonarchTextStyle.Title, heading = true)
    Row(verticalAlignment = Alignment.CenterVertically) {
        MonarchText(text = {{description}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted, modifier = Modifier.weight(1f))
        MonarchIcon(SampleIcons.Rss, contentDescription = null, size = MonarchIconSize.Sm)
        MonarchLink(text = "RSS feed", onClick = {}, variant = MonarchLinkVariant.Standalone)
    }
    LazyColumn(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space6)) {
        items(releases, key = { it.id }) { release ->
            Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
              Box(
                  modifier = Modifier
                      .padding(top = MonarchTheme.spacing.space1)
                      .size(MonarchTheme.spacing.space3)
                      .border(2.dp, MonarchTheme.colors.accentStrong, CircleShape),
              )
              Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2), verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(
                        text = dates.format(Date(release.date)),
                        style = MonarchTextStyle.Caption,
                        color = MonarchTheme.colors.textMuted,
                    )
                    release.version?.let { MonarchText(text = it, style = MonarchTextStyle.Code) }
                }
                MonarchText(text = release.title, style = MonarchTextStyle.Heading)
                FlowRow(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1)) {
                    release.tags.forEach { MonarchBadge(text = it.label, tone = it.tone) }
                }
                release.body?.let { body ->
                    MonarchProse(style = MonarchProseStyle(limitLineLength = false)) { paragraph(body) }
                }
                release.href?.let { href ->
                    MonarchLink(
                        text = "Read more",
                        onClick = { uriHandler.openUri(href) },
                        variant = MonarchLinkVariant.Standalone,
                        external = true,
                    )
                }
              }
            }
        }
    }
}

